/**
 * Real professional icon assets extracted from templates/dark.pptx's own
 * campaign-slide metric cards (ppt/media/image5.png, image7.png, image2.png,
 * image13.png, image6.png, image4.png, image11.png — identified by parsing
 * ppt/slides/slide2.xml and matching each <p:pic>'s enclosing card group to
 * its {{METRIC_*}} tag: image5->AD SPEND, image7->REACH, image2->IMPRESSIONS,
 * image13->RESULTS, image6->CTR (All), image4->COST PER RESULT, image11->CPC
 * (All)). Downscaled from the template's native 2048x2048px (2048px is
 * massive overkill for an icon that renders at ~16pt on a slide — cut base64
 * size by ~97% with no visible quality loss at render size) to 120x120px via
 * Pillow, PNG-optimized. Replaces the emoji-icon design used in an earlier
 * pass of the dynamic metric card system, per explicit product direction:
 * dynamic cards should use the deck's own icon set, not emoji substitutes.
 *
 * Used by dynamic-cards.ts, which embeds each icon (see
 * pptx/embed-image.ts's embedImageInSlide machinery) once per distinct icon
 * actually used in a report — not once per card — since every campaign/
 * ad-set slide in the deck shares one `template.campaign` rels part (see
 * render.ts), so one relationship per icon is reused across every card on
 * every slide that needs it.
 */

export type MetricIconId = "spend" | "reach" | "impressions" | "results" | "ctr" | "cost" | "cpc";

export interface MetricIconAsset {
  id: MetricIconId;
  /** Base64-encoded PNG bytes (120x120px, transparent background, white glyph — matches the template's own dark-card icon style). */
  base64: string;
  widthPx: number;
  heightPx: number;
}

